<?php
$u=sr_auth('candidate');sr_page_heading('THEO DÕI ỨNG TUYỂN','Đơn ứng tuyển của tôi','Cập nhật tiến độ hồ sơ và xem kết quả so khớp AI.');
$items=sr_all('SELECT a.*,j.title,j.company,j.location,i.scheduled_at,i.location AS interview_location,i.meeting_url,i.status AS interview_status,i.note AS interview_note,ir.response AS interview_reply,ir.note AS reply_note FROM applications a JOIN jobs j ON j.id=a.job_id LEFT JOIN interviews i ON i.application_id=a.id LEFT JOIN interview_responses ir ON ir.application_id=a.id WHERE a.candidate_id=? ORDER BY a.id DESC',[$u['id']]);
if(!$items):?><div class="panel empty-state"><h2>Chưa có đơn ứng tuyển</h2><p>Hãy khám phá công việc phù hợp và nộp hồ sơ của bạn.</p><a class="button primary" href="<?=sr_url('home')?>">Tìm việc ngay</a></div><?php else:?><div class="panel table-panel"><div class="table-responsive"><table><thead><tr><th>Vị trí tuyển dụng</th><th>Ngày ứng tuyển</th><th>Điểm AI</th><th>Trạng thái</th><th>Kỹ năng cần bổ sung</th><th>Phỏng vấn</th></tr></thead><tbody><?php foreach($items as $item):?><tr><td><strong><?=h($item['title'])?></strong><small><?=h($item['company'])?> · <?=h($item['location'])?></small></td><td><?=h(sr_date($item['created_at']))?></td><td><?php if($item['score']!==null):?><strong class="score-pill"><?=number_format((float)$item['score'],0)?>%</strong><?php else:?><span class="muted">Chưa đánh giá</span><?php endif;?></td><td><span class="badge <?=sr_state_class($item['status'])?>"><?=h(sr_status($item['status']))?></span></td><td><?=h($item['missing_skills']?:'Không phát hiện')?></td><td><?php if($item['scheduled_at']):?><strong><?=h(sr_date($item['scheduled_at']))?> <?=h(date('H:i',strtotime($item['scheduled_at'])))?></strong><small><?=h($item['interview_status']==='scheduled'?'Đã lên lịch':($item['interview_status']==='completed'?'Hoàn thành':'Đã hủy'))?></small><?php if($item['interview_location']):?><small><?=h($item['interview_location'])?></small><?php endif;?><?php if($item['meeting_url'] && sr_validate_url($item['meeting_url'])):?><a href="<?=h($item['meeting_url'])?>" target="_blank" rel="noopener noreferrer">Link phỏng vấn ↗</a><?php endif;?><?php if($item['interview_note']):?><small><?=h($item['interview_note'])?></small><?php endif;?><?php if($item['interview_status']==='scheduled'):?><div class="interview-reply"><small><strong>Phản hồi:</strong> <?=h($item['interview_reply']==='accepted'?'Đã xác nhận':($item['interview_reply']==='reschedule'?'Đã đề nghị đổi lịch':'Chưa phản hồi'))?></small><form method="post" class="stack-form"><?=sr_token()?><input type="hidden" name="action" value="interview_response"><input type="hidden" name="back" value="applications"><input type="hidden" name="application_id" value="<?=(int)$item['id']?>"><label>Phản hồi lịch<select name="response" required><option value="accepted">Xác nhận tham gia</option><option value="reschedule">Đề nghị đổi lịch</option></select></label><label>Ghi chú (bắt buộc nếu đổi lịch)<textarea name="response_note" maxlength="1000" rows="2" placeholder="Ví dụ: Xin đổi sang 14:00 ngày kế tiếp..."></textarea></label><button class="button secondary sm">Gửi phản hồi</button></form></div><?php endif;?><?php else:?><span class="muted">Chưa lên lịch</span><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div><div class="privacy-note">Điểm AI là thước đo so khớp tham khảo, không phản ánh xác suất được tuyển dụng.</div><?php endif;?>
